CREATE OR REPLACE FUNCTION public.knoux_bridge_lock_allowed_bridge(p_bridge_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current text;
begin
  if p_bridge_id !~ '^[0-9a-f]{16,64}$' then
    return false;
  end if;

  select allowed_bridge_id into v_current
  from public.knoux_bridge_control_config
  where singleton = true
  for update;

  if v_current is null then
    update public.knoux_bridge_control_config
    set allowed_bridge_id = p_bridge_id,
        updated_at = now()
    where singleton = true;
    return true;
  end if;

  return v_current = p_bridge_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.knoux_bridge_mint_ticket(p_owner_id uuid, p_bridge_id text, p_sid text, p_scopes text[], p_ttl_seconds integer DEFAULT 60)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'pgsodium', 'extensions'
AS $function$
declare
  v_fingerprint text;
  v_secret_id uuid;
  v_secret_key bytea;
  v_now bigint;
  v_ttl integer;
  v_header text;
  v_claims text;
  v_header_b64 text;
  v_claims_b64 text;
  v_input text;
  v_sig bytea;
  v_sig_b64 text;
  v_invalid_scope text;
begin
  if p_owner_id is null
     or p_bridge_id is null
     or p_sid is null
     or coalesce(array_length(p_scopes, 1), 0) = 0 then
    raise exception 'invalid-ticket-request';
  end if;

  if not exists (
    select 1
    from public.knoux_bridge_machines m
    where m.owner_id = p_owner_id
      and m.bridge_id = p_bridge_id
      and m.status <> 'revoked'
  ) then
    raise exception 'machine-not-authorized';
  end if;

  select s
    into v_invalid_scope
    from unnest(p_scopes) as s
   where s not in (
     'terminal:open',
     'git:read',
     'metrics:read',
     'proc:list',
     'logs:read',
     'fs:read'
   )
   limit 1;

  if v_invalid_scope is not null then
    raise exception 'scope-not-allowlisted';
  end if;

  v_ttl := greatest(1, least(coalesce(p_ttl_seconds, 60), 60));
  v_now := floor(extract(epoch from clock_timestamp()))::bigint;

  select k.fingerprint, k.vault_secret_id
    into v_fingerprint, v_secret_id
    from public.knoux_bridge_signing_keys k
   where k.active = true
   order by k.created_at desc
   limit 1;

  if v_secret_id is null then
    raise exception 'signing-key-unavailable';
  end if;

  select decode(v.decrypted_secret, 'base64')
    into v_secret_key
    from vault.decrypted_secrets v
   where v.id = v_secret_id
   limit 1;

  if v_secret_key is null then
    raise exception 'signing-secret-unavailable';
  end if;

  v_header := jsonb_build_object(
    'alg', 'EdDSA',
    'typ', 'KNX-TKT',
    'kid', left(v_fingerprint, 16)
  )::text;

  v_claims := jsonb_build_object(
    'iss', 'knoux-bff',
    'aud', p_bridge_id,
    'sub', p_owner_id::text,
    'sid', p_sid,
    'scope', to_jsonb(p_scopes),
    'jti', gen_random_uuid()::text,
    'iat', v_now,
    'exp', v_now + v_ttl
  )::text;

  v_header_b64 := replace(
    replace(
      rtrim(replace(encode(convert_to(v_header, 'utf8'), 'base64'), E'\n', ''), '='),
      '+', '-'
    ),
    '/', '_'
  );

  v_claims_b64 := replace(
    replace(
      rtrim(replace(encode(convert_to(v_claims, 'utf8'), 'base64'), E'\n', ''), '='),
      '+', '-'
    ),
    '/', '_'
  );

  v_input := v_header_b64 || '.' || v_claims_b64;

  v_sig := pgsodium.crypto_sign_detached(
    convert_to(v_input, 'utf8'),
    v_secret_key
  );

  v_sig_b64 := replace(
    replace(
      rtrim(replace(encode(v_sig, 'base64'), E'\n', ''), '='),
      '+', '-'
    ),
    '/', '_'
  );

  return v_input || '.' || v_sig_b64;
end;
$function$

