CREATE OR REPLACE FUNCTION public.submit_contact_request(p_name text, p_email text, p_message text, p_phone text DEFAULT NULL::text, p_company text DEFAULT NULL::text, p_request_type text DEFAULT NULL::text, p_source_path text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if length(trim(coalesce(p_name,''))) < 2 then
    raise exception 'invalid_name';
  end if;
  if position('@' in coalesce(p_email,'')) < 2 then
    raise exception 'invalid_email';
  end if;
  if length(trim(coalesce(p_message,''))) < 10 then
    raise exception 'invalid_message';
  end if;

  insert into public.contact_requests(
    user_id, name, email, phone, company, request_type,
    message, source_path, metadata
  )
  values (
    (select auth.uid()),
    trim(p_name),
    lower(trim(p_email)),
    nullif(trim(p_phone),''),
    nullif(trim(p_company),''),
    nullif(trim(p_request_type),''),
    trim(p_message),
    nullif(trim(p_source_path),''),
    coalesce(p_metadata,'{}'::jsonb)
  )
  returning id into v_id;

  return v_id;
end;
$function$

